-- Columns dropped from brz_partsupp:
--   ps_comment                   free-text filler generated by TPC-H, no analytical value
--   _batch_id, _source_relation  Bronze audit metadata: lineage questions are answered in Bronze;
--                                _loaded_at is kept (used by deduplicate and as freshness marker)

with source as (
    {{ deduplicate(ref('brz_partsupp'), partition_by=['ps_partkey', 'ps_suppkey']) }}
)

select
    -- keys
    {{ dbt_utils.generate_surrogate_key(['ps_partkey', 'ps_suppkey']) }}::varchar as part_supplier_id,
    ps_partkey::varchar            as part_id,
    ps_suppkey::varchar            as supplier_id,

    -- measures
    ps_availqty::number(38, 0)     as available_quantity,
    ps_supplycost::number(12, 2)   as supply_cost,

    _loaded_at
from source
